def merge_intervals(intervals):
    if not intervals:
        return []
    merged = []
    for start, end in sorted(intervals):
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged

import heapq


def toposort(nodes, edges):
    in_degree = {node: 0 for node in nodes}
    adj = {node: [] for node in nodes}

    seen_edges = set()
    for src, dst in edges:
        if (src, dst) in seen_edges:
            continue
        seen_edges.add((src, dst))
        adj[src].append(dst)
        in_degree[dst] += 1

    heap = [node for node in nodes if in_degree[node] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        node = heapq.heappop(heap)
        result.append(node)
        for neighbor in adj[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                heapq.heappush(heap, neighbor)

    if len(result) != len(nodes):
        raise ValueError("Graph contains a cycle")

    return result

import re


def parse_env(text):
    """Parse environment assignments from text into a dict."""
    key_pattern = re.compile(r'^[A-Za-z_][A-Za-z0-9_]*$')
    result = {}
    for line in text.splitlines():
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Invalid environment assignment: {stripped!r}")
        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()
        if len(value) >= 2 and value[0] == value[-1] and value[0] in ("'", '"'):
            value = value[1:-1]
        if not key_pattern.match(key):
            raise ValueError(f"Invalid environment key: {key!r}")
        result[key] = value
    return result

def parse_sse(chunks):
    buffer = b''
    events = []
    current_data = []

    for chunk in chunks:
        buffer += chunk
        while True:
            nl = buffer.find(b'\n')
            if nl == -1:
                break
            line = buffer[:nl]
            buffer = buffer[nl + 1:]
            if line.endswith(b'\r'):
                line = line[:-1]
            # Splitting on \n (0x0A) never bisects a UTF-8 multibyte char,
            # so decoding each complete \n-delimited segment is safe even
            # when a chunk boundary split the character.
            text = line.decode('utf-8', errors='replace')

            if not text:
                # Blank line dispatches an event.
                if current_data:
                    data = '\n'.join(current_data)
                    if data == '[DONE]':
                        return events  # exclude and stop processing everything after
                    events.append(data)
                    current_data = []
            elif text.startswith(':'):
                # Comment line.
                pass
            else:
                colon = text.find(':')
                if colon != -1:
                    name = text[:colon]
                    value = text[colon + 1:]
                    if name == 'data':
                        if value.startswith(' '):
                            value = value[1:]  # remove at most one space
                        current_data.append(value)
            # Other field types (event/id/retry/...) are ignored.
            # If no colon at all, the whole line is a field name with no value -> ignored.

    return events

import math


def retry_delay(attempt, base, cap):
    # Validate arguments.
    if attempt < 0:
        raise ValueError("attempt must be nonnegative")
    if base < 0:
        raise ValueError("base must be nonnegative")
    if cap < 0:
        raise ValueError("cap must be nonnegative")
    if not math.isfinite(base):
        raise ValueError("base must be finite")
    if not math.isfinite(cap):
        raise ValueError("cap must be finite")

    base = float(base)
    cap = float(cap)

    # Any zero factor makes the product 0, and min(cap, 0) == 0 because cap >= 0.
    if base == 0 or cap == 0:
        return 0.0

    # value = base * 2**attempt.
    # Represent base = mant * 2**exp with 0.5 <= mant < 1, so
    # value = mant * 2**(exp + attempt).  Build it with ldexp so the huge
    # power of two is never materialized and no intermediate overflows.
    mant, exp = math.frexp(base)
    k = exp + attempt

    try:
        value = math.ldexp(mant, k)  # mant * 2**k
    except OverflowError:
        value = math.inf
    except ValueError:
        # Subnormal/underflow result that ldexp cannot represent.
        value = 0.0

    return min(cap, value)

def fifo_admit(active, queued, budget, slots):
    for q in queued:
        if q > budget:
            raise ValueError("queued reservation exceeds budget")

    used = sum(active)
    available_slots = slots - len(active)

    admitted = []
    remaining = []

    for i, q in enumerate(queued):
        if available_slots > 0 and used + q <= budget:
            admitted.append(q)
            used += q
            available_slots -= 1
        else:
            remaining = list(queued[i:])
            break

    return admitted, remaining
